package ink.warrant.instrument

class AcmeH2Driver : Driver {
    override fun decode(bytes: ByteArray): Double? {
        if (bytes.size < 3) return null
        if (bytes[0] != 1.toByte()) return null
        val low = bytes[1].toInt() and 0xFF
        val high = bytes[2].toInt() and 0xFF
        val value = (high shl 8) or low
        return value / 100.0
    }
}
